# trace: PRD-TRACE-005, PRD-CORE-038
"""The header writer of generated source files.

Each generated source file that permits comments starts with two comment
lines (PRD-TRACE-005):

    # Generated by dsml <major>. Do not edit.
    # Elements: <identity>, <identity>

The header gives only the major version of the toolchain (PRD-CORE-038).
Thus a minor or patch release does not change the output. The identities
are in sorted order, with no duplicates. A file type that does not permit
comments, for example JSON, gets no header.
"""

import enum
from importlib import metadata
from pathlib import PurePosixPath

PROG = "dsml"


class FileType(enum.StrEnum):
    """The file types of the generated files."""

    DOCKERFILE = "dockerfile"
    HCL = "hcl"
    HTML = "html"
    """An HTML page, for example `index.html`. The header has only line comments, thus
    an HTML page gets no header."""
    IGNORE = "ignore"
    """An ignore file, for example `.dockerignore`."""
    INI = "ini"
    """An INI file, for example `alembic.ini`."""
    JAVASCRIPT = "javascript"
    JSON = "json"
    PYTHON = "python"
    TOML = "toml"
    TYPESCRIPT = "typescript"
    YAML = "yaml"


# The comment start of each file type. None: the file type does not permit
# comments.
_COMMENT: dict[FileType, str | None] = {
    FileType.DOCKERFILE: "#",
    FileType.HCL: "#",
    FileType.HTML: None,
    FileType.IGNORE: "#",
    FileType.INI: "#",
    FileType.JAVASCRIPT: "//",
    FileType.JSON: None,
    FileType.PYTHON: "#",
    FileType.TOML: "#",
    FileType.TYPESCRIPT: "//",
    FileType.YAML: "#",
}

_SUFFIXES: dict[str, FileType] = {
    ".hcl": FileType.HCL,
    ".html": FileType.HTML,
    ".ini": FileType.INI,
    ".js": FileType.JAVASCRIPT,
    ".json": FileType.JSON,
    ".py": FileType.PYTHON,
    ".tf": FileType.HCL,
    ".toml": FileType.TOML,
    ".ts": FileType.TYPESCRIPT,
    ".tsx": FileType.TYPESCRIPT,
    ".yaml": FileType.YAML,
    ".yml": FileType.YAML,
}


def file_type_of(path: str) -> FileType:
    """Give the file type of a generated file from its path."""
    name = PurePosixPath(path).name
    if name == "Dockerfile" or name.endswith(".Dockerfile"):
        return FileType.DOCKERFILE
    if name.endswith("ignore") and name.startswith("."):
        return FileType.IGNORE
    file_type = _SUFFIXES.get(PurePosixPath(name).suffix)
    if file_type is None:
        raise ValueError(f'The file "{path}" does not have a known file type.')
    return file_type


def comment_start(file_type: FileType) -> str | None:
    """Give the comment start of a file type, or None if it does not permit comments."""
    return _COMMENT[file_type]


# trace: PRD-CORE-038
def major_version(version: str | None = None) -> str:
    """Give the major version of the toolchain.

    Without `version`, the function reads the version of the installed
    toolchain package.
    """
    if version is None:
        version = metadata.version(PROG)
    major = version.split(".", 1)[0]
    if not major.isdecimal():
        raise ValueError(f'The toolchain version "{version}" does not start with a major version.')
    return str(int(major))


# trace: PRD-TRACE-005, PRD-CORE-031, PRD-CORE-038
def header(file_type: FileType, elements: list[str], version: str | None = None) -> str:
    """Give the header of a generated source file, with an LF after each line.

    The result is an empty text for a file type that does not permit comments.
    """
    for identity in elements:
        if not identity or identity != identity.strip() or "\n" in identity or "\r" in identity:
            raise ValueError(f"The element identity {identity!r} is not correct for a header.")
    start = comment_start(file_type)
    if start is None:
        return ""
    identities = ", ".join(sorted(set(elements)))
    elements_line = f"{start} Elements: {identities}" if identities else f"{start} Elements:"
    return f"{start} Generated by {PROG} {major_version(version)}. Do not edit.\n{elements_line}\n"
